-- Plan finished-goods delivery before gate-pass and dispatch posting.
create sequence if not exists public.seq_dispatch_schedule start 1;
create table public.dispatch_schedules(dispatch_schedule_id uuid primary key default gen_random_uuid(),schedule_no text not null unique,finished_goods_id uuid not null references public.finished_goods(finished_goods_id),customer_id uuid not null references public.customers(customer_id),scheduled_date date not null,delivery_location text,vehicle_no text,driver_name text,quantity numeric not null check(quantity>0),uom_id uuid not null references public.uoms(uom_id),status text not null default'PLANNED' check(status in('PLANNED','READY','DISPATCHED','CANCELLED')),remarks text,created_at timestamptz not null default now(),created_by text not null default'system',updated_at timestamptz not null default now(),updated_by text);
create unique index one_active_dispatch_schedule on public.dispatch_schedules(finished_goods_id)where status in('PLANNED','READY');
create or replace function public.schedule_factory_dispatch(p_finished_goods uuid,p_date date,p_location text,p_vehicle text,p_driver text,p_remarks text default null)returns uuid language plpgsql security definer set search_path=public as $$declare v_id uuid;v_no text;v_customer uuid;v_qty numeric;v_uom uuid;begin if not has_factory_role(auth.uid(),array['admin','store'])then raise exception'not authorized';end if;if p_date<current_date then raise exception'scheduled date cannot be in the past';end if;select o.customer_id,fg.quantity,fg.uom_id into v_customer,v_qty,v_uom from finished_goods fg join production_batches b using(production_batch_id)join production_orders po using(production_order_id)join order_items oi using(order_item_id)join orders o using(order_id)where fg.finished_goods_id=p_finished_goods and fg.status='AVAILABLE';if v_customer is null then raise exception'finished goods are not available';end if;v_no:='DS-'||to_char(current_date,'YYYYMMDD')||'-'||lpad(nextval('seq_dispatch_schedule')::text,4,'0');insert into dispatch_schedules(schedule_no,finished_goods_id,customer_id,scheduled_date,delivery_location,vehicle_no,driver_name,quantity,uom_id,remarks,created_by)values(v_no,p_finished_goods,v_customer,p_date,p_location,p_vehicle,p_driver,v_qty,v_uom,p_remarks,auth.uid()::text)returning dispatch_schedule_id into v_id;insert into audit_log(user_id,action,entity_type,entity_id,new_value)values(auth.uid(),'Dispatch Scheduled','dispatch_schedules',v_id,jsonb_build_object('schedule_no',v_no,'finished_goods_id',p_finished_goods,'scheduled_date',p_date,'quantity',v_qty));return v_id;end$$;
alter table public.dispatch_schedules enable row level security;create policy factory_read_dispatch_schedules on public.dispatch_schedules for select using(has_factory_role(auth.uid(),array['admin','store','production_manager','viewer']));grant execute on function public.schedule_factory_dispatch(uuid,date,text,text,text,text)to authenticated;
